import cv2, numpy as np
im=cv2.imread('first_frame.png')
# ramp polygon edge samples around y rows: print intensity transitions x 170..220
for y in [0,5,10,15,20,25,30,35,40,45,50,55,60,65,68,70,72,75]:
 vals=[]
 for x in range(170,221):
  b,g,r=im[y,x]
  if r>g+4 and g>b+1 and r<190:
   vals.append(x)
 # groups
 groups=[]
 for x in vals:
  if not groups or x>groups[-1][-1]+1: groups.append([x])
  else: groups[-1].append(x)
 print(y, [(a[0],a[-1]) for a in groups])
